    Source: packages/compose-gen/specs/organisms/meat-cards.json
    The meat of a grill dish as picture cards in one radio group (fieldset with role radiogroup named by its legend): a picture, the name and the price per 500 g; the first checked.
    Props (p): name, legend, options. *}
{var $v_name = ($p['name'] ?? null)}
{var $v_legend = ($p['legend'] ?? null)}
{var $v_options = ($p['options'] ?? null)}
{capture $c_7}
  {capture $c_1}
    {=og_text($v_legend)}
  {/capture}
  {=og_include('compose/Legend.latte', ['size' => 'sm', 'class' => 'mb-2', 'attrs' => og_attrs(['id', og_tpl('{0}-legend', [$v_name])]), 'children' => (string) $c_1])|noescape}
  {capture $c_6}
    {foreach og_l($v_options) as $v_o}
      {var $v_i = $iterator->counter0}
      {capture $c_5}
        {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_o, ['name']), 'ratio' => '4/3']])|noescape}
        {capture $c_3}
          {=og_include('compose/Radio.latte', ['name' => og_s($v_name), 'value' => og_s(og_get($v_o, ['id'])), 'checked' => og_t(og_eq($v_i, 0))])|noescape}
          {capture $c_2}
            {=og_text(og_get($v_o, ['name']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['children' => (string) $c_2])|noescape}
        {/capture}
        {=og_include('compose/Label.latte', ['class' => 'flex items-center gap-2 font-medium', 'children' => (string) $c_3])|noescape}
        {capture $c_4}
          {=og_text(og_tpl('{0} · {1}', [og_money(og_get($v_o, ['price']), og_get($v_o, ['currency'])), og_get($v_o, ['note'])]))}
        {/capture}
        {=og_include('compose/Inline.latte', ['class' => 'text-xs text-muted-foreground', 'children' => (string) $c_4])|noescape}
      {/capture}
      {=og_include('compose/Box.latte', ['class' => 'flex flex-col gap-2 rounded p-2 text-sm inset-ring inset-ring-border has-checked:bg-muted has-checked:inset-ring-foreground', 'attrs' => og_attrs(['data-slot', 'option']), 'children' => (string) $c_5])|noescape}
    {/foreach}
  {/capture}
  {=og_include('compose/Box.latte', ['class' => 'grid grid-cols-2 gap-4 md:grid-cols-4', 'children' => (string) $c_6])|noescape}
{/capture}
{=og_include('compose/Fieldset.latte', ['class' => 'flex flex-col gap-2', 'attrs' => og_attrs(['role', 'radiogroup', 'aria-labelledby', og_tpl('{0}-legend', [$v_name]), 'data-slot', 'meat']), 'children' => (string) $c_7])|noescape}
